(() => {
 const tabs=[...document.querySelectorAll('[data-bundle-mode]')],panel=document.querySelector('#mode-preview');
 const modes={both:['화면도, 도구도 함께.','블루레몬에이드의 색과 글꼴을 적용하고, 필요한 내장 확장을 따로 켜서 사용해요.',true,true],theme:['읽기 편한 테마만.','색·글꼴·채팅 화면을 꾸며요. 내장 확장은 실행하지 않고 저장한 설정은 보관해요.',true,false],extensions:['쓰던 테마에, 필요한 도구만.','블루레몬에이드의 화면 스타일을 적용하지 않고 내장 확장을 사용해요. 각 도구는 따로 켜고 끌 수 있어요.',false,true]};
 function select(tab){const [title,description,theme,tools]=modes[tab.dataset.bundleMode];for(const t of tabs){t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;}panel.setAttribute('aria-labelledby',tab.id);panel.querySelector('[data-mode-title]').textContent=title;panel.querySelector('[data-mode-description]').textContent=description;panel.querySelector('[data-mode-theme]').textContent=theme?'테마 사용':'테마 미적용';panel.querySelector('[data-mode-tools]').textContent=tools?'내장 확장 사용':'내장 확장 꺼짐';panel.querySelector('[data-mode-theme]').classList.toggle('off',!theme);panel.querySelector('[data-mode-tools]').classList.toggle('off',!tools);}
 tabs.forEach((tab,i)=>{tab.onclick=()=>select(tab);tab.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;select(tabs[next]);tabs[next].focus();};});
})();
